import java.util.*; public class VendingMachine { enum Coin {ONE,TWO,FIVE,TEN} public static void main(String[] x){ Scanner s=new Scanner(System.in); int total=0; while(total<15){System.out.print("Coin (ONE/TWO/FIVE/TEN): "); Coin c=Coin.valueOf(s.next().toUpperCase()); int v=switch(c){case ONE->1;case TWO->2;case FIVE->5;case TEN->10;}; total+=v; System.out.println("Total: "+total);} System.out.println("Paid. Change: "+(total-15)); }}
